@using sv_c31156bcead942e680dafa799a1b0cb1.Services

<div class="profile-section">
    <h2>Profile Settings</h2>

    @if (_profile is not null)
    {
        <div class="avatar-preview">
            <img src="@_displayName" alt="Avatar" style="display:none;" />
            <div class="avatar-image">
                <img src="@_avatarUrl" alt="Avatar preview" />
            </div>
            <p class="avatar-url">@_avatarUrl</p>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" rows="4" @bind="_bio"></textarea>
        </div>

        <div class="form-group">
            <label for="avatarUrl">Avatar URL</label>
            <input id="avatarUrl" type="text" @bind="_avatarUrl" />
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
            <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Profile saved successfully!</div>
        }
    }
    else
    {
        <p>Loading profile...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        LoadFromProfile(_profile);
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _avatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        if (_profile is not null)
        {
            LoadFromProfile(_profile);
        }
        _showSuccess = false;
    }
}

@using sv_c31156bcead942e680dafa799a1b0cb1.Services

<div class="notifications-section">
    <h2>Notification Preferences</h2>

    @if (_prefs is not null)
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_emailNotifications" />
                <span>Email Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="_pushNotifications" />
                <span>Push Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <div class="channels-section">
            <h3>Muted Channels</h3>
            <p class="help-text">Check channels you want to mute.</p>
            @foreach (var channel in _channels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@channel.IsMuted"
                           @onchange="e => ToggleChannel(channel.Name, (bool)(e.Value ?? false))" />
                    <span>#@channel.Name</span>
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Notification preferences saved!</div>
        }
    }
    else
    {
        <p>Loading preferences...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = new();
    private bool _showSuccess;

    private class ChannelState
    {
        public string Name { get; set; } = "";
        public bool IsMuted { get; set; }
    }

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _channels = _prefs.MutedChannels.Select(c => new ChannelState { Name = c, IsMuted = true }).ToList();

        // Add some common channels that aren't muted for demonstration
        var allChannels = new[] { "general", "random", "announcements", "watercooler", "dev", "design" };
        foreach (var ch in allChannels.Where(c => !_prefs.MutedChannels.Contains(c)))
        {
            _channels.Add(new ChannelState { Name = ch, IsMuted = false });
        }
        _channels = _channels.OrderBy(c => c.Name).ToList();
    }

    private void ToggleChannel(string name, bool muted)
    {
        var channel = _channels.FirstOrDefault(c => c.Name == name);
        if (channel is not null)
        {
            channel.IsMuted = muted;
        }
    }

    private async Task SaveAsync()
    {
        var mutedChannels = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@using sv_c31156bcead942e680dafa799a1b0cb1.Services

<div class="security-section">
    <h2>Security Settings</h2>

    @if (_security is not null)
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>Change Password</span>
                <span class="expand-icon">@(_passwordPanelOpen ? "▾" : "▸")</span>
            </button>

            @if (_passwordPanelOpen)
            {
                <div class="panel-content">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="error-message">@_passwordError</div>
                    }
                    @if (_passwordSuccess)
                    {
                        <div class="toast success">Password updated successfully!</div>
                    }
                    <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="twofa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="twofa-status">
                <label class="toggle-item">
                    <input type="checkbox" checked="@_security.TwoFactorEnabled" disabled />
                    <span>
                        @if (_security.TwoFactorEnabled)
                        {
                            <span class="status-badge enabled">Enabled</span>
                        }
                        else
                        {
                            <span class="status-badge disabled">Disabled</span>
                        }
                    </span>
                </label>
            </div>
            @if (_security.LastPasswordChange.HasValue)
            {
                <p class="help-text">Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _security.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id == "current")
                                {
                                    <span class="current-badge">Current</span>
                                }
                                else
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation="true">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                    <div class="button-group">
                        <button class="btn btn-danger" @onclick="RevokeSessionAsync">Revoke</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
    else
    {
        <p>Loading security settings...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _security;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private bool _passwordSuccess;
    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = "";
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordSuccess = true;
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeSessionAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _security = await SettingsService.GetSecuritySettingsAsync();
            _sessionToRevoke = null;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 5) return "Just now";
        if (diff.TotalHours < 1) return $"{(int)diff.TotalMinutes} minutes ago";
        if (diff.TotalDays < 1) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

