@using sv_c31156bcead942e680dafa799a1b0cb1.Services

<div class="notifications-section">
    <h2>Notification Preferences</h2>

    @if (_prefs is not null)
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_emailNotifications" />
                <span>Email Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="_pushNotifications" />
                <span>Push Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <div class="channels-section">
            <h3>Muted Channels</h3>
            <p class="help-text">Check channels you want to mute.</p>
            @foreach (var channel in _channels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@channel.IsMuted"
                           @onchange="e => ToggleChannel(channel.Name, (bool)(e.Value ?? false))" />
                    <span>#@channel.Name</span>
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Notification preferences saved!</div>
        }
    }
    else
    {
        <p>Loading preferences...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = new();
    private bool _showSuccess;

    private class ChannelState
    {
        public string Name { get; set; } = "";
        public bool IsMuted { get; set; }
    }

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _channels = _prefs.MutedChannels.Select(c => new ChannelState { Name = c, IsMuted = true }).ToList();

        // Add some common channels that aren't muted for demonstration
        var allChannels = new[] { "general", "random", "announcements", "watercooler", "dev", "design" };
        foreach (var ch in allChannels.Where(c => !_prefs.MutedChannels.Contains(c)))
        {
            _channels.Add(new ChannelState { Name = ch, IsMuted = false });
        }
        _channels = _channels.OrderBy(c => c.Name).ToList();
    }

    private void ToggleChannel(string name, bool muted)
    {
        var channel = _channels.FirstOrDefault(c => c.Name == name);
        if (channel is not null)
        {
            channel.IsMuted = muted;
        }
    }

    private async Task SaveAsync()
    {
        var mutedChannels = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

